/* GENERATED by tools/gen_hw_caps.py for board revision A - DO NOT EDIT. */
/*
 * Derived from that revision's OWN netlist, not from the current
 * schematic. Regenerate with: python3 tools/gen_hw_caps.py
 */
#ifndef O2P_HW_CAPS_REV_A_H
#define O2P_HW_CAPS_REV_A_H

/* ---- Is there an ADS1119 on this revision? ----
 *
 * Rev B deletes U8 and converts every analog channel on the STM32G071's
 * own SAR. When 0, the O2P_HW_ADC_AIN*_NET macros DO NOT EXIST - a
 * #ifdef on them is a compile error rather than a silent zero, which is
 * the point: code that reads an ADS channel on a board with no ADS
 * should fail to build, not fail at 3 a.m. in a windrow.
 */
#define O2P_HW_HAS_ADS1119 1

/* ---- ADS1119 single-ended inputs, as this revision actually wires them ---- */
#define O2P_HW_ADC_AIN0_NET "/ADC_AFE_VOUT"
#define O2P_HW_ADC_AIN1_NET "/ADC_VREF_MON"
#define O2P_HW_ADC_AIN2_NET "/ADC_VA_MON"
#define O2P_HW_ADC_AIN3_NET "/ADC_VIN_MON"

/* ---- Is the cell bias measurable on this board? ----
 *
 * 1 only when the two channels the firmware reads for WE and RE are
 * NAMED as the electrode buffers - ADS AIN2/AIN3 on Rev A, MCU PA0/PA1
 * on Rev B.
 *
 * WHAT THIS DOES NOT PROVE, because a reviewer asked and the honest
 * answer is 'less than it looks': this matches NET NAMES. It does not
 * trace the net to U7.12/U7.13, and it cannot - ADC_WE_BUF is the
 * OUTPUT of a follower whose input is CELL_WE, so the two are different
 * nets by design and net identity can never connect them. A revision
 * that names a net /ADC_WE_BUF while wiring it elsewhere would read as
 * capable. That is a smaller risk than the one this replaced - a
 * hand-maintained flag nobody re-checked - but it is not zero, and a
 * bench check of WE against 0.67 x VREF is still the thing that
 * actually confirms it on a new board.
 * When 0, cell_bias_mv is not a measurement of the cell and the bias
 * existence check must not produce a verdict from it - the guard's
 * third state, BIAS_UNKNOWN, is what it gets. Calibration stays gated
 * either way, because bias_verified_recently() refuses UNKNOWN.
 *
 * This revision: WE channel = /ADC_VA_MON, RE channel = /ADC_VIN_MON.
 */
#define O2P_HW_BIAS_ADC_REACHES_ELECTRODES 0

/* ---- Reference topology, for diagnosis only ----
 *
 * AFE reference pin U7.11 -> /VREF_TRIM
 * converter reference U8.7 (ADS REFP) -> /VREF_TRIM
 *
 * SHARING A NET IS NOT OBSERVABILITY. Even when these are the same
 * node, no converter on the board can see an OPEN SOLDER JOINT at
 * U7 pin 11: the net stays at 2.5 V and the monitor reads it happily
 * while the die is not attached to anything. Measured 2026-09-09 -
 * vref reported 2490 mV while the AFE's internal zero was 0 V and
 * every derived current was fiction. Do not build a guard on this.
 */
#define O2P_HW_VREF_NET_SHARED_WITH_AFE 1

/* ---- RS-485 receiver enable: can this board be commanded deaf? ----
 *
 * THVD1410 /RE is U5 pin 2 and is ACTIVE LOW. The part's 0.1 uA
 * standby needs /RE HIGH with DE LOW, which is unreachable when the
 * two share a net - Rev A does, and its receiver therefore burns
 * 700 uA forever, 24 % of the board's idle draw (POWER-BUDGET.md).
 *
 * 1 requires BOTH that /RE has a net of its own AND that the net
 * reaches the MCU pin the firmware drives. A rework that lifts the
 * pin but never lands the wire is not a capability.
 *
 * This revision: U5.2 = /RS485_DE, U5.3 = /RS485_DE,
 *                MCU pin 31 (PC7) = unconnected-(U6-PC7-Pad31).
 *
 * When 0, o2p_modbus_rx_standby(true) must REFUSE rather than write a
 * pin that goes nowhere and report a standby that did not happen.
 */
#define O2P_HW_RS485_RE_ON_ITS_OWN_PIN 0

/* Is LISTENING the passive default - R45, 47k from /RE to GND?
 *
 * /RE floats HIGH on the transceiver's ~2 MOhm internal pull-up and
 * every MCU GPIO is high-impedance out of reset, so without this a
 * probe sitting in its RS-485 bootloader, or with no working
 * application at all, is DEAF - and a potted one is unrecoverable.
 * That is the field-reflash path of SCHEMATIC-REVIEW.md M2.
 *
 * 0 on a board whose /RE is not split is not a missing part: there is
 * nothing for it to pull down, and R7 on the shared net already does
 * this job. 0 on a board that IS split is a fitting error, and the
 * probe must not be potted until it is fixed.
 */
#define O2P_HW_RS485_RE_PASSIVE_PULLDOWN 0

/* ---- MCU ADC pin connectivity ---- */
#define O2P_HW_MCU_PA0_NET "unconnected-(U6-PA0-Pad11)"
#define O2P_HW_MCU_PA1_NET "unconnected-(U6-PA1-Pad12)"
#define O2P_HW_MCU_PA4_NET "unconnected-(U6-PA4-Pad15)"
#define O2P_HW_MCU_PA5_NET "unconnected-(U6-PA5-Pad16)"
#define O2P_HW_MCU_PA6_NET "unconnected-(U6-PA6-Pad17)"
#define O2P_HW_MCU_PB1_NET "/ADC_DRDY"
/* The oxygen channel itself. 0 with O2P_HW_HAS_ADS1119 also 0 means this
 * board cannot measure oxygen at all. */
#define O2P_HW_AFE_VOUT_ON_MCU 0
/* ---- Is the ADC's full scale the 2.500 V reference, or VDDA? ----
 *
 * The architecture fact, from ONE pad: the MCU's VREF+ pin.
 * This revision: U6.5 -> /3V3D
 *
 * When 1, the oxygen equation has NO code_REF term and V_REF is a
 * COMPILE-TIME CONSTANT (O2P_HW_VREF_MV):
 *     I = V_REF x (0.67 - code_AFE / 4095) / R_TIA
 * The three-conversion form is the VDDA-architecture equation. Porting it
 * here would read a channel that saturates at 4095, leaving 0.06 %O2 of
 * zero error at EG = -5 LSB that no air-point calibration removes.
 */
#define O2P_HW_VREF_IS_ADC_REFERENCE 0
#define O2P_HW_CE_MON_CONNECTED 0
#define O2P_HW_VIN_MON_ON_MCU 0
#define O2P_HW_VIN_MON_ON_ADS 1
#define O2P_HW_VA_MON_ON_ADS 1

/* ---- VREF monitor scaling, PER REVISION ----
 *
 * This used to come from hw_contract.h (O2P_HW_DIV_VREF_*), derived from
 * R34/R35 in the LIVE schematic. That was a landmine: deleting R34/R35 for
 * Rev B on 2026-09-12 would have made the contract say 1:1 and the Rev A
 * bench board - which really does read a 47k/47k HALVED copy on ADS AIN1 -
 * report 1250 mV instead of 2500 and trip its own VREF gate. Same shape as
 * the 2026-09-09 channel-map failure, so it belongs on the same side of the
 * split: a fabricated board's scale factor is a property of the COPPER.
 *
 * Rev A: R34/R35, 47k/47k -> multiply the reading by 2.
 * Rev B: /VREF_TRIM straight onto PA5, no divider -> multiply by 1.
 */
/* Rev A: the reference is a MEASURED channel and VDDA is the full scale. */
#define O2P_HW_DIV_VREF_MON_NUM 47000u
#define O2P_HW_DIV_VREF_MON_DEN 94000u

/* ---- ADS1119 rail divider scaling (Rev A: R24/R25 10k/10k, R26/R27 130k/20k) ---- */
#define O2P_HW_DIV_VA_ADS_NUM   10000u
#define O2P_HW_DIV_VA_ADS_DEN   20000u
#define O2P_HW_DIV_VIN_ADS_NUM  20000u
#define O2P_HW_DIV_VIN_ADS_DEN 150000u

#endif /* O2P_HW_CAPS_REV_A_H */
